Link: https://patch.msgid.link/20260604165938.32033-1-leontyevantony@gmail.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The function netvsc_copy_to_send_buf() in netvsc.c uses phys_to_virt() on a PFN from a page buffer entry to obtain a kernel virtual address for copying. On 32-bit x86 with CONFIG_HIGHMEM, this PFN may reference a high memory page (above LOWMEM), causing phys_to_virt() to return an invalid address. The subsequent memcpy() then faults in the transmit softirq path, which is fatal.

Here is the patch:
 #include <linux/wait.h>
 #include <linux/mm.h>
+#include <linux/highmem.h>
 #include <linux/delay.h>
 #include <linux/io.h>

 static void netvsc_copy_to_send_buf(struct netvsc_device *net_device,
 				    unsigned int section_index,
 				    u32 pend_size,
 				    struct hv_netvsc_packet *packet,
 				    struct rndis_message *rndis_msg,
 				    struct hv_page_buffer *pb,
 				    bool xmit_more)
 {
 	char *start = net_device->send_buf;
 	char *dest = start + (section_index * net_device->send_section_size)
 		     + pend_size;
 	int i;
 	u32 padding = 0;
 	u32 page_count = packet->cp_partial ? 1 : packet->page_buf_cnt;
 	u32 remain;

 	/* Add padding */
 	remain = packet->total_data_buflen & (net_device->pkt_align - 1);
 	if (xmit_more && remain) {
 		padding = net_device->pkt_align - remain;
 		rndis_msg->msg_len += padding;
 		packet->total_data_buflen += padding;
 	}

 	for (i = 0; i < page_count; i++) {
-		char *src = phys_to_virt(pb[i].pfn << HV_HYP_PAGE_SHIFT);
-		u32 offset = pb[i].offset;
+		phys_addr_t paddr = (pb[i].pfn << HV_HYP_PAGE_SHIFT) +
+				    pb[i].offset;
 		u32 len = pb[i].len;

-		memcpy(dest, (src + offset), len);
-		dest += len;
+		while (len) {
+			struct page *page = phys_to_page(paddr);
+			u32 off = offset_in_page(paddr);
+			u32 chunk = min_t(u32, len, PAGE_SIZE - off);
+			char *src = kmap_local_page(page);
+
+			memcpy(dest, src + off, chunk);
+			kunmap_local(src);
+			dest += chunk;
+			paddr += chunk;
+			len -= chunk;
+		}
 	}

 	if (padding)
 		memset(dest, 0, padding);
 }



